text:
Here's your water tracker: tap + to add a glass, − to undo, and it counts toward 8 for today. It resets each day and remembers your count if the page can save it.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Water tracker</title>
<style>
  body { font-family: system-ui, sans-serif; background: #eef6fb; margin: 0; padding: 24px; display: flex; justify-content: center; }
  .card { background: #fff; border-radius: 16px; padding: 24px; width: 100%; max-width: 360px; text-align: center; box-shadow: 0 2px 10px rgba(0,0,0,.08); }
  h1 { font-size: 20px; margin: 0 0 4px; }
  .date { color: #667; font-size: 13px; margin-bottom: 16px; }
  .count { font-size: 48px; font-weight: 700; color: #1a73b8; }
  .goal { color: #667; margin-bottom: 12px; }
  .bar { height: 12px; background: #dbeaf5; border-radius: 6px; overflow: hidden; margin-bottom: 16px; }
  .fill { height: 100%; width: 0; background: #1a9be0; transition: width .3s; }
  .glasses { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; margin-bottom: 20px; min-height: 36px; }
  .glass { font-size: 26px; opacity: .25; }
  .glass.on { opacity: 1; }
  button { font-size: 20px; border: 0; border-radius: 10px; padding: 10px 22px; margin: 0 4px; cursor: pointer; }
  .add { background: #1a9be0; color: #fff; }
  .sub { background: #dbeaf5; color: #1a5a85; }
  .reset { background: none; color: #889; font-size: 13px; margin-top: 16px; text-decoration: underline; }
  .msg { margin-top: 14px; min-height: 20px; color: #2a8a4a; font-weight: 600; }
</style>
</head>
<body>
<div class="card">
  <h1>💧 Water today</h1>
  <div class="date" id="date"></div>
  <div class="count" id="count">0</div>
  <div class="goal">of 8 glasses</div>
  <div class="bar"><div class="fill" id="fill"></div></div>
  <div class="glasses" id="glasses"></div>
  <button class="sub" id="minus" type="button">−</button>
  <button class="add" id="plus" type="button">+ Glass</button>
  <div class="msg" id="msg"></div>
  <button class="reset" id="reset" type="button">Reset today</button>
</div>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var n = 0;
  try { n = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch (e) {}

  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }

  function draw() {
    document.getElementById("date").textContent = new Date().toDateString();
    document.getElementById("count").textContent = n;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    var g = document.getElementById("glasses");
    g.innerHTML = "";
    for (var i = 0; i < Math.max(GOAL, n); i++) {
      var s = document.createElement("span");
      s.className = "glass" + (i < n ? " on" : "");
      s.textContent = "🥛";
      g.appendChild(s);
    }
    var m = document.getElementById("msg");
    if (n >= GOAL) m.textContent = "Goal reached. Nice work! 🎉";
    else m.textContent = (GOAL - n) + " to go";
  }

  document.getElementById("plus").onclick = function () { n++; save(); draw(); };
  document.getElementById("minus").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
